// C002-T-029 — the OpenCode target package (C002-IF-005 §2) on fx-dist: `dist/opencode/` generated by the
// generator into a temporary folder, in both enforcement modes, and read back from disk. Expected values
// come from the mapping table and the source plugin, never from a copy (C002-CAP-01 acceptance,
// verification note).
//   C002-TC-124 (C002-TS-124)  the Serena declaration of opencode.json (OpenCode row; the Copilot row is C002-T-031's)
//   C002-TC-201 (C002-TS-201)  package layout: ten agents, 13 commands, the skills, the MCP servers
//   C002-TC-202 (C002-TS-202)  fx-dist-bad: a server removed from opencode.json is reported (TGT-MCP-001)
//   C002-TC-203 (C002-TS-203)  agent modes: conductor primary, nine specialists subagent
//   C002-TC-204 (C002-TS-204)  every command bound to the conductor, no guard line
//   C002-TC-205 (C002-TS-205)  install notes
//   C002-TC-225 (C002-TS-225)  command file names `architect-<name>.md`
//   C002-TC-227 (C002-TS-227)  fx-dist-bad: `architect-new.md` renamed `new.md` is reported (TGT-LAYOUT-001)
// Beside them: the closed tool map of each agent entry (C002-IF-001 §6.1), the inlined skills and no
// `memory` field. C002-TC-226 needs an OpenCode host: tests/replay/scenarios/opencode-host.test.ts.
// C002-TC-125 (Serena started from this declaration): tests/integration/cap01/serena-launch.test.ts.
import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, readdirSync, readFileSync, rmSync, statSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { declaredServers, INSTALL_SOURCE, openCodePackageFindings } from "../../../scripts/generate/emit/opencode.ts";
import { emitsQuickLint } from "../../../scripts/generate/emit/opencode-quicklint.ts";
import { main } from "../../../scripts/generate/main.ts";
import { readSource } from "../../../scripts/generate/reader.ts";
import { loadTargetTable, TARGETS, type MappingTable, type Mode } from "../../../scripts/generate/tables.ts";
import { CONDUCTOR, listField, translateAgents } from "../../../scripts/generate/translate/frontmatter.ts";
import { skillHeading } from "../../../scripts/generate/translate/inline.ts";
import { MANIFEST } from "../../../scripts/generate/writer.ts";
import { splitFrontmatter } from "../../../src/model/frontmatter.ts";
import { repoRoot } from "../../helpers.ts";

const root = repoRoot();
const PLUGIN = join(root, "plugins", "architect");
const read = readSource(PLUGIN);
assert.deepEqual(read.diagnostics, [], "the source plugin reads without diagnostics");
const source = read.source;
const table: MappingTable = loadTargetTable(root, "opencode");
const peers = TARGETS.map((t) => loadTargetTable(root, t));
const MODES: Mode[] = ["native-permissions", "sdd-mcp-server"];
const agentNames = source.agents.map((a) => a.name).sort();
const commandNames = source.commands.map((c) => c.name).sort();
const AGENTS_DIR = table.placement["agents_dir"]!;
const COMMANDS_DIR = table.placement["commands_dir"]!;
const SKILLS_DIR = table.placement["skills_dir"]!;
const CONFIG = table.placement["config_file"]!;
const INSTALL = table.placement["install_notes"]!;

/** Every file under `dir` (relative, `/`-separated) with its text. */
function readTree(dir: string): Map<string, string> {
  const out = new Map<string, string>();
  const walk = (abs: string, rel: string) => {
    for (const name of readdirSync(abs).sort()) {
      const p = join(abs, name);
      const r = rel === "" ? name : `${rel}/${name}`;
      if (statSync(p).isDirectory()) walk(p, r);
      else out.set(r, readFileSync(p, "utf8"));
    }
  };
  walk(dir, "");
  return out;
}

/** fx-dist: the OpenCode package generated for `mode`, read back from disk (built once per mode). */
const packages = new Map<Mode, Map<string, string>>();
function fxDist(mode: Mode): Map<string, string> {
  const hit = packages.get(mode);
  if (hit) return hit;
  const base = mkdtempSync(join(tmpdir(), "sdd-fx-dist-"));
  try {
    const err: string[] = [];
    const code = main(["--target", "opencode", "--mode", `opencode=${mode}`, "--out", join(base, "dist"), "--quiet"], { cwd: root, stdout: () => {}, stderr: (l) => err.push(l) });
    assert.equal(code, 0, err.join("\n"));
    const files = readTree(join(base, "dist", "opencode"));
    packages.set(mode, files);
    return files;
  } finally {
    rmSync(base, { recursive: true, force: true });
  }
}

const front = (text: string) => {
  const d = splitFrontmatter(text);
  assert.ok(d.data, "the file has a frontmatter mapping");
  return { data: d.data, body: d.lines.slice(d.bodyStartLine - 1).join("\n") };
};
const config = (files: Map<string, string>) => JSON.parse(files.get(CONFIG)!) as { $schema: string; mcp: Record<string, { type: string; command?: string[]; url?: string }>; tools: Record<string, boolean>; agent: Record<string, { tools: Record<string, boolean>; permission?: Record<string, unknown> }>; permission?: unknown };
const inDir = (files: Map<string, string>, dir: string) => [...files.keys()].filter((p) => p.startsWith(`${dir}/`)).map((p) => p.slice(dir.length + 1));
const emitInput = (mode: Mode) => ({ source, table, target: "opencode" as const, mode, peers });

for (const mode of MODES) {
  test(`C002-TC-201 (C002-TS-201) [${mode}]: the package holds the ten agents, the 13 commands, every skill and the MCP servers of the table`, () => {
    const files = fxDist(mode);
    assert.equal(agentNames.length, 10);
    assert.equal(commandNames.length, 13);
    assert.deepEqual(inDir(files, AGENTS_DIR).sort(), agentNames.map((n) => `${n}.md`));
    assert.deepEqual(inDir(files, COMMANDS_DIR).sort(), commandNames.map((n) => `architect-${n}.md`).sort());
    for (const s of source.skills) {
      assert.ok(files.has(`${SKILLS_DIR}/${s.name}/SKILL.md`), `${s.name}/SKILL.md`);
      for (const r of s.resources) assert.ok(files.has(`${SKILLS_DIR}/${r.path.slice("skills/".length)}`), r.path);
    }
    assert.deepEqual(new Set(inDir(files, SKILLS_DIR).map((p) => p.split("/")[0])), new Set(source.skills.map((s) => s.name)));
    const c = config(files);
    assert.equal(c.$schema, "https://opencode.ai/config.json");
    for (const s of ["context7", "deepwiki", "serena"]) assert.ok(s in c.mcp, `opencode.json declares ${s}`);
    assert.deepEqual(Object.keys(c.mcp).sort(), declaredServers(table, mode), "exactly the servers of the table for the mode");
    assert.deepEqual(c.tools, Object.fromEntries(declaredServers(table, mode).map((s) => [`${s}*`, false])), "the Architect servers are off for every other agent");
    for (const [name, s] of Object.entries(table.mcp_servers).filter(([, s]) => s.modes.includes(mode)))
      assert.deepEqual(c.mcp[name], s.transport === "http" ? { type: "remote", url: s.url } : { type: "local", command: [s.command, ...(s.args ?? [])] }, name);
    assert.ok(files.has(MANIFEST) && files.has(INSTALL));
    assert.deepEqual(openCodePackageFindings(files, emitInput(mode)), [], "the target structure findings of a clean package");
    // + the quick-lint plugin of C002-T-030 where the mode and the table call for it (C002-REQ-215).
    assert.equal(files.size, 10 + 13 + source.skills.reduce((n, s) => n + 1 + s.resources.length, 0) + 3 + (emitsQuickLint(table, mode) ? 1 : 0), "nothing else");
  });

  test(`C002-TC-203 (C002-TS-203) [${mode}]: sdd-conductor is primary, the nine specialists are subagents, each with the model of its tier`, () => {
    const files = fxDist(mode);
    for (const a of source.agents) {
      const { data } = front(files.get(`${AGENTS_DIR}/${a.name}.md`)!);
      assert.equal(data["mode"], a.name === CONDUCTOR ? "primary" : "subagent", a.name);
      assert.equal(data["model"], table.models[a.data!["model"] as "opus" | "sonnet" | "haiku"], a.name);
      assert.equal(typeof data["description"], "string");
      assert.ok(!("memory" in data) && !("tools" in data) && !("effort" in data) && !("color" in data), `${a.name}: no memory, tools, effort or color field`);
    }
  });

  test(`closed tool set [${mode}]: each agent entry of opencode.json starts with "*": false and turns on exactly the derived tools`, () => {
    const files = fxDist(mode);
    const c = config(files);
    assert.equal(c.permission, undefined, "no top-level permission key");
    assert.deepEqual(Object.keys(c.agent).sort(), agentNames, "agent entries for the ten Architect agents only");
    const derived = translateAgents(emitInput(mode));
    assert.deepEqual(derived.diagnostics, []);
    const text = files.get(CONFIG)!;
    for (const a of derived.agents) {
      const entry = c.agent[a.frontmatter.name]!;
      assert.equal(Object.keys(entry.tools)[0], "*", `${a.frontmatter.name}: the catch-all comes first`);
      assert.equal(entry.tools["*"], false);
      assert.deepEqual(
        Object.entries(entry.tools).filter(([k]) => k !== "*").map(([k, v]) => [k, v]).sort(),
        a.frontmatter.tools.map((t) => [t, true]).sort(),
        `${a.frontmatter.name}: tools`,
      );
      assert.deepEqual(entry.permission?.["task"], a.frontmatter.name === CONDUCTOR ? { "*": "deny", ...Object.fromEntries(agentNames.filter((n) => n !== CONDUCTOR).map((n) => [n, "allow"])) } : "deny");
    }
    assert.ok(text.indexOf('"*": false') < text.indexOf('"glob": true'), "the catch-all is written before the named entries");
  });

  test(`inlined skills [${mode}]: each agent body ends with its source skills under "## Skill: <name>", in order`, () => {
    const files = fxDist(mode);
    for (const a of source.agents) {
      const { body } = front(files.get(`${AGENTS_DIR}/${a.name}.md`)!);
      let at = -1;
      for (const s of listField(a.data!["skills"])) {
        const i = body.indexOf(`\n${skillHeading(s)}\n`);
        assert.ok(i > at, `${a.name}: ${s} inlined after the previous skill`);
        at = i;
      }
    }
  });
}

test("C002-TC-124 (C002-TS-124): the serena entry of opencode.json runs sdd serena-launch --user-data --read-only -- start-mcp-server, then the table's Serena arguments", () => {
  for (const mode of MODES) {
    const c = config(fxDist(mode));
    const command = c.mcp["serena"]!.command!;
    assert.equal(command[0], "sdd");
    assert.deepEqual(command.slice(1, 6), ["serena-launch", "--user-data", "--read-only", "--", "start-mcp-server"]);
    const args = table.mcp_servers["serena"]!.args!;
    assert.deepEqual(args.slice(0, 5), ["serena-launch", "--user-data", "--read-only", "--", "start-mcp-server"], "the table's own form");
    assert.deepEqual(command.slice(6), args.slice(5), "followed by the Serena arguments of the mapping table");
    const entry = JSON.stringify(c.mcp["serena"]);
    for (const banned of ["${CLAUDE_PLUGIN_ROOT}", "${CLAUDE_PLUGIN_DATA}", "SERENA_HOME"]) assert.ok(!entry.includes(banned), `no ${banned}`);
  }
});

test("C002-TC-204 (C002-TS-204): each of the 13 commands has agent sdd-conductor and no claude --agent guard line", () => {
  const files = fxDist(table.enforcement_mode);
  for (const name of commandNames) {
    const text = files.get(`${COMMANDS_DIR}/architect-${name}.md`)!;
    const { data } = front(text);
    assert.equal(data["agent"], CONDUCTOR, name);
    assert.equal(typeof data["description"], "string");
    assert.ok(!text.includes("claude --agent architect:sdd-conductor"), `${name}: no guard line`);
    assert.ok(!/^This command runs in the `architect:sdd-conductor` main session\./m.test(text), name);
  }
});

test("C002-TC-205 (C002-TS-205): the install notes state the prerequisites, the architect-sdd install, the placement and the conductor start", () => {
  const files = fxDist(table.enforcement_mode);
  const notes = files.get(INSTALL)!;
  const version = (JSON.parse(readFileSync(join(PLUGIN, ".claude-plugin", "plugin.json"), "utf8")) as { version: string }).version;
  const tested = table.host.tested_versions["opencode"]!;
  assert.ok(source.files.some((f) => f.path === INSTALL_SOURCE), "the install-notes source is part of the source plugin");
  assert.ok(!notes.includes("{{"), "every token resolved");
  assert.match(notes, /Node\.js 20 or later/);
  assert.ok(notes.includes(`OpenCode ${tested}, the tested version`), "the tested version of the table");
  // The doctor remedies table of the generated doctor command names the same tested version.
  assert.ok(files.get(`${COMMANDS_DIR}/architect-doctor.md`)!.includes(`tested version: ${tested}`));
  assert.match(notes, /Claude models of the three tiers \(Opus, Sonnet and Haiku\)/);
  assert.ok(notes.includes(`npm install -g architect-sdd@${version}`));
  assert.ok(notes.includes("`.opencode/`") && notes.includes("`opencode.json`"), "placement of .opencode/ and opencode.json");
  assert.match(notes, /select the agent `sdd-conductor`/);
  assert.match(notes, /sdd MCP server enforcement/, "the enforcement mode by its glossary name");
});

test("C002-TC-225 (C002-TS-225): the command files are exactly architect-<name>.md, new and init included, no new.md or init.md", () => {
  const names = inDir(fxDist(table.enforcement_mode), COMMANDS_DIR).sort();
  assert.deepEqual(names, commandNames.map((n) => `architect-${n}.md`).sort());
  for (const n of ["architect-new.md", "architect-init.md"]) assert.ok(names.includes(n), n);
  for (const n of ["new.md", "init.md"]) assert.ok(!names.includes(n), n);
});

test("C002-TC-202 (C002-TS-202): fx-dist-bad without deepwiki in opencode.json is reported naming opencode.json and deepwiki", () => {
  const mode = table.enforcement_mode;
  const bad = new Map(fxDist(mode));
  const c = config(bad);
  delete c.mcp["deepwiki"];
  bad.set(CONFIG, JSON.stringify(c, null, 2) + "\n");
  const findings = openCodePackageFindings(bad, emitInput(mode));
  const mcp = findings.filter((f) => f.code === "TGT-MCP-001");
  assert.equal(mcp.length, 1, JSON.stringify(findings));
  assert.equal(mcp[0]!.file, "opencode.json");
  assert.ok(mcp[0]!.message.includes("opencode.json") && mcp[0]!.message.includes('"deepwiki"'), mcp[0]!.message);
});

test("C002-TC-227 (C002-TS-227): fx-dist-bad with architect-new.md renamed new.md is reported naming new.md", () => {
  const mode = table.enforcement_mode;
  const bad = new Map(fxDist(mode));
  const from = `${COMMANDS_DIR}/architect-new.md`;
  bad.set(`${COMMANDS_DIR}/new.md`, bad.get(from)!);
  bad.delete(from);
  const findings = openCodePackageFindings(bad, emitInput(mode));
  assert.ok(findings.every((f) => f.code === "TGT-LAYOUT-001"), JSON.stringify(findings));
  assert.ok(findings.some((f) => f.file === `${COMMANDS_DIR}/new.md` && f.message.includes("new.md")), JSON.stringify(findings));
  assert.ok(findings.some((f) => f.file === from), "the missing architect-new.md is named too");
});
